#include <iostream>
using namespace std;

template <typename... Args>
int countAll(Args... args) {
    return sizeof...(args);
}

template <typename... Args>
int addAll(Args... args) {
    return (args + ... + 0);
}

template <typename... Args>
void printAll(Args... args) {
    (cout << ... << args);
    cout << endl;
}

int main() {
    int n = 0;
